import * as duckdb from 'https://cdn.jsdelivr.net/npm/@duckdb/duckdb-wasm@1.29.0/+esm';
const $=id=>document.getElementById(id);
let conn, rows=[],busy=false;
const usd=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(Number(n));
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function where(){const region=$('region').value,year=$('year').value;const terms=[];if(region)terms.push(`region = '${region.replaceAll("'","''")}'`);if(year)terms.push(`year = ${Number(year)}`);return terms.length?'WHERE '+terms.join(' AND '):'';}
function sql(){const w=where();return {
 monthly:`SELECT year, month, round(CAST(sum(revenue) AS DOUBLE),2) AS revenue\nFROM sales ${w}\nGROUP BY year, month ORDER BY year, month;`,
 rollup:`SELECT coalesce(region,'ALL MARKETS') AS market,\n round(CAST(sum(revenue) AS DOUBLE),2) AS revenue\nFROM sales ${w}\nGROUP BY ROLLUP(region) ORDER BY revenue DESC;`,
 pivot:`SELECT category,\n CAST(sum(CASE WHEN year=2024 THEN revenue ELSE 0 END) AS DOUBLE) AS revenue_2024,\n CAST(sum(CASE WHEN year=2025 THEN revenue ELSE 0 END) AS DOUBLE) AS revenue_2025\nFROM sales ${w}\nGROUP BY category ORDER BY category;`,
 ranking:`SELECT category, round(CAST(sum(revenue) AS DOUBLE),2) AS revenue,\n dense_rank() OVER (ORDER BY sum(revenue) DESC) AS rank\nFROM sales ${w}\nGROUP BY category ORDER BY rank;`
}[$('query').value];}
async function query(s){const result=await conn.query(s);return result.toArray().map(r=>r.toJSON());}
async function run(){const statement=sql();$('sql').textContent=statement;rows=await query(statement);if(!rows.length){$('results').textContent='No matching rows.';return;}const cols=Object.keys(rows[0]);$('results').innerHTML='<table><thead><tr>'+cols.map(c=>`<th>${escape(c)}</th>`).join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+cols.map(c=>`<td>${escape(r[c])}</td>`).join('')+'</tr>').join('')+'</tbody></table>';}
async function refresh(){const t=performance.now();const w=where();const [k]=await query(`SELECT CAST(sum(revenue) AS DOUBLE) revenue,count(*) count,avg(revenue) average FROM sales ${w}`);$('revenue').textContent=usd(k.revenue);$('count').textContent=Number(k.count).toLocaleString('en-US');$('average').textContent=usd(k.average);const markets=await query(`SELECT region,CAST(sum(revenue) AS DOUBLE) revenue FROM sales ${w} GROUP BY region ORDER BY revenue DESC`);const max=Math.max(...markets.map(x=>Number(x.revenue)),1);$('bars').innerHTML=markets.map(x=>`<div class="barrow"><div class="barlabel"><span>${escape(x.region)}</span><span>${usd(x.revenue)}</span></div><div class="track"><div class="fill" style="width:${Number(x.revenue)/max*100}%"></div></div></div>`).join('');await run();$('timing').textContent=`${Math.round(performance.now()-t)} ms · browser elapsed`;}
async function guarded(fn){if(busy)return;busy=true;['apply','run','download'].forEach(id=>$(id).disabled=true);$('error').textContent='';try{await fn();}catch(e){$('error').textContent=String(e);}finally{busy=false;['apply','run','download'].forEach(id=>$(id).disabled=false);}}
$('apply').onclick=()=>guarded(refresh);$('run').onclick=()=>guarded(run);$('query').onchange=()=>{$('sql').textContent=sql();};$('download').onclick=()=>{if(!rows.length)return;const cols=Object.keys(rows[0]);const cell=v=>'"'+String(v??'').replaceAll('"','""')+'"';const csv=[cols,...rows.map(r=>cols.map(c=>r[c]))].map(r=>r.map(cell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download='olap-results.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
try{const bundle=await duckdb.selectBundle(duckdb.getJsDelivrBundles());const workerURL=URL.createObjectURL(new Blob([`importScripts("${bundle.mainWorker}");`],{type:'text/javascript'}));const db=new duckdb.AsyncDuckDB(new duckdb.ConsoleLogger(),new Worker(workerURL));await db.instantiate(bundle.mainModule,bundle.pthreadWorker);URL.revokeObjectURL(workerURL);conn=await db.connect();const response=await fetch('model.sql');if(!response.ok)throw new Error('Cannot load model.sql');await conn.query(await response.text());$('status').textContent='DuckDB is ready · 100,000 rows';await guarded(refresh);}catch(e){$('status').textContent='Engine unavailable';$('error').textContent='DuckDB could not start. Check your internet connection and CDN access, then reload.\n'+String(e);}
